            "p": "巳 هو الفرع الأرضي السادس من بين الفروع الأرضية الاثني عشر، وينتمي إلى الثعبان. عندما يكون فرع شهر الميلاد 巳، يكون الفصل هو الصيف والعنصر الذي يملك الفصل هو النار."
