            "p": "عندما يكون فرع يوم الميلاد 巳، فإن هذه الشخصية هي موقع الزوج. يمكنك أدناه أن ترى أي السيقان يحتويها هذا الفرع وما تكونه بالنسبة إلى ساق اليوم."
