    "summary": "يتم مقارنة العمود اليومي اليوم مع الرسم البياني الفلكي لتسجيل النقاط. يتم الكشف عن ثلاثة عشر علاقة دعم وقمع وسبع علاقات فروع أرضية، جنبًا إلى جنب مع جميع العناصر العشرين وإضافاتها وخصوماتها.",
